If you do want a plugin for this specific case, you could maybe try something like this:
Spoiler
JavaScript:
/*:
 * @plugindesc
 * "Message Text" will search past the end of conditional branches.
 */

Game_Interpreter.prototype.command101 = (alias => function(params) {
    let result = alias.call(params);
    if (result && [101, 401].contains(this.currentCommand().code) && !this.command412) {
        while (this._list[this._index + 1] && [0, 412].contains(this.nextEventCode())) {
            this._index++;
        }
        switch (this.nextEventCode()) {
            case 102: // Show Choices
                this._index++;
                this.setupChoices(this.currentCommand().parameters);
                break;
            case 103: // Input Number
                this._index++;
                this.setupNumInput(this.currentCommand().parameters);
                break;
            case 104: // Select Item
                this._index++;
                this.setupItemChoice(this.currentCommand().parameters);
                break;
        }
    }
    return result;
})(Game_Interpreter.prototype.command101);

I would suggest solving it using the "Label" and "Jump To Label" features along with a plugin. Basically, add this plugin to your project (or at the end of existing plugin) and start using labels. Place a "Jump To Label" command right after the text, and put a "Label" command just before the choice you want to jump to.
The plugin will check whether there's a "Jump To Label" after the text, verify that a choice command follows that label, and then merge the commands automatically.
Spoiler:
usage example
Spoiler:
plugin
JavaScript:
(function() {

    Game_Interpreter.prototype.command101 = function(params) {
        if ($gameMessage.isBusy()) {
            return false;
        }

        $gameMessage.setFaceImage(params[0], params[1]);
        $gameMessage.setBackground(params[2]);
        $gameMessage.setPositionType(params[3]);
        $gameMessage.setSpeakerName(params[4]);

        while (this.nextEventCode() === 401) {
            this._index++;
            $gameMessage.add(this.currentCommand().parameters[0]);
        }

        switch (this.nextEventCode()) {
            case 102:
                this._index++;
                this.setupChoices(this.currentCommand().parameters);
                break;
            case 103:
                this._index++;
                this.setupNumInput(this.currentCommand().parameters);
                break;
            case 104:
                this._index++;
                this.setupItemChoice(this.currentCommand().parameters);
                break;
            case 119:
                this.setupInputFromLabel();
                break;
        }

        this.setWaitMode("message");
        return true;
    };

    Game_Interpreter.prototype.setupInputFromLabel = function() {
        const labelName = this._list[this._index + 1].parameters[0];

        for (let i = 0; i < this._list.length; i++) {
            const cmd = this._list[i];
            if (cmd.code === 118 && cmd.parameters[0] === labelName) {
                const nextCmd = this._list[i + 1];
                if (nextCmd && [102, 103, 104].includes(nextCmd.code)) {
                    this._index++;
                    this.jumpTo(i + 1);

                    switch (this.currentCommand().code) {
                        case 102:
                            this.setupChoices(this.currentCommand().parameters);
                            break;
                        case 103:
                            this.setupNumInput(this.currentCommand().parameters);
                            break;
                        case 104:
                            this.setupItemChoice(this.currentCommand().parameters);
                            break;
                    }
                }
                break;
            }
        }
    };

})();

