(function() {

    const _Game_Interpreter_command101 = Game_Interpreter.prototype.command101; 
    Game_Interpreter.prototype.command101 = function(params) {
        const result = _Game_Interpreter_command101.call(this, params);

        if (result && this.nextEventCode() === 119) {
            this.setupInputFromLabel();
        }

        return result;
    };

    Game_Interpreter.prototype.setupInputFromLabel = function() {
        const labelName = this._list[this._index + 1].parameters[0];

        for (let i = 0; i < this._list.length; i++) {
            const cmd = this._list[i];
            if (cmd.code === 118 && cmd.parameters[0] === labelName) {
                const nextCmd = this._list[i + 1];
                if (nextCmd && [102, 103, 104].includes(nextCmd.code)) {
                    this._index++;
                    this.jumpTo(i + 1);
                    this._indent = this.currentCommand().indent;
                    switch (this.currentCommand().code) {
                        case 102:
                            this.setupChoices(this.currentCommand().parameters);
                            break;
                        case 103:
                            this.setupNumInput(this.currentCommand().parameters);
                            break;
                        case 104:
                            this.setupItemChoice(this.currentCommand().parameters);
                            break;
                    }
                }
                break;
            }
        }
    };

})();
